From 87904109ca7e2557ebe8c28c55dc9d6baeca924b Mon Sep 17 00:00:00 2001
From: yushijinhun <yushijinhun@gmail.com>
Date: Sat, 7 Jul 2018 17:26:20 +0800
Subject: [PATCH] [TransitionHandler]Set mouseTransparent of the whole view ,
 fix bug introduced in 3fb5048f103ed958bdd87207f6b6c929b5ef7eca


diff --git a/HMCL/src/main/java/org/jackhuang/hmcl/ui/animation/TransitionHandler.java b/HMCL/src/main/java/org/jackhuang/hmcl/ui/animation/TransitionHandler.java
index cec4a9d47..b350bb9a2 100644
--- a/HMCL/src/main/java/org/jackhuang/hmcl/ui/animation/TransitionHandler.java
+++ b/HMCL/src/main/java/org/jackhuang/hmcl/ui/animation/TransitionHandler.java
@@ -86,7 +86,7 @@ public final class TransitionHandler implements AnimationHandler {
             Timeline nowAnimation = new Timeline();
             nowAnimation.getKeyFrames().addAll(transition.animate(this));
             nowAnimation.getKeyFrames().add(new KeyFrame(duration, e -> {
-                previousNode.setMouseTransparent((Boolean) previousNode.getProperties().get(MOUSE_TRANSPARENT));
+                view.setMouseTransparent(false);
                 view.getChildren().remove(previousNode);
             }));
             nowAnimation.play();
@@ -105,14 +105,12 @@ public final class TransitionHandler implements AnimationHandler {
         if (previousNode == newView)
             previousNode = NULL;

-        previousNode.getProperties().put(MOUSE_TRANSPARENT, previousNode.isMouseTransparent());
-        previousNode.setMouseTransparent(true);
+        view.setMouseTransparent(true);

         currentNode = newView;

         view.getChildren().setAll(previousNode, currentNode);
     }

-    private static final String MOUSE_TRANSPARENT = "TransitionHandler.MOUSE_TRANSPARENT";
     private static final StackPane NULL = new StackPane();
 }
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by the incorrect handling of the `mouseTransparent` property during transitions. Specifically, the previous implementation only set the `mouseTransparent` state for the `previousNode`, which could lead to unintended user interactions with that node while it was still part of the view. This could result in a confusing user experience, as the `previousNode` might still receive mouse events even when it should not be interactive. The fix ensures that the entire `view` is set to be mouse transparent during the transition, preventing any interactions with the `previousNode`.

        Commit message:
        [TransitionHandler]Set mouseTransparent of the whole view ,
 fix bug introduced in 3fb5048f103ed958bdd87207f6b6c929b5ef7eca  

        Patch:

     public void setContent(Node newView, AnimationProducer transition, Duration duration) {
         this.duration = duration;

         Timeline prev = animation;
         if (prev != null)
             prev.stop();

         updateContent(newView);

         transition.init(this);

         // runLater or "init" will not work
         Platform.runLater(() -> {
             Timeline nowAnimation = new Timeline();
             nowAnimation.getKeyFrames().addAll(transition.animate(this));
             nowAnimation.getKeyFrames().add(new KeyFrame(duration, e -> {
-                previousNode.setMouseTransparent((Boolean) previousNode.getProperties().get(MOUSE_TRANSPARENT));
+                view.setMouseTransparent(false);
                 view.getChildren().remove(previousNode);
             }));
             nowAnimation.play();
             animation = nowAnimation;
         });
     }

     private void updateContent(Node newView) {
         if (view.getWidth() > 0 && view.getHeight() > 0) {
             previousNode = currentNode;
             if (previousNode == null)
                 previousNode = NULL;
         } else
             previousNode = NULL;

         if (previousNode == newView)
             previousNode = NULL;

-        previousNode.getProperties().put(MOUSE_TRANSPARENT, previousNode.isMouseTransparent());
-        previousNode.setMouseTransparent(true);
+        view.setMouseTransparent(true);

         currentNode = newView;

         view.getChildren().setAll(previousNode, currentNode);
     }

-    private static final String MOUSE_TRANSPARENT = "TransitionHandler.MOUSE_TRANSPARENT";
     private static final StackPane NULL = new StackPane();
 }


